/** Compact weighted-catalogue encoding (phase 2). Each row is a zigzag varint of the
 * seed delta followed by a varint weight (>= 1); the text is base64 (whitespace ignored).
 * decodeCatalogue returns the interleaved [seed, cumulative weight] layout the
 * engine already binary-searches. Generated by phase2/builders/install-p2.mjs. */
export type Catalogue = ArrayLike<number>;
function base64Bytes(text: string): Uint8Array {
  const clean = text.replace(/\s+/g, '');
  const bin = typeof atob === 'function' ? atob(clean) : '';
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
export function decodeCatalogue(text: string, rows: number, total: number): Catalogue {
  const bytes = base64Bytes(text), out = new Uint32Array(rows * 2);
  let p = 0, seed = 0, cumulative = 0;
  const varint = (): number => { let v = 0, scale = 1, b: number; do { b = bytes[p++]!; v += (b & 127) * scale; scale *= 128; } while (b & 128); return v; };
  for (let r = 0; r < rows; r++) {
    const z = varint(); seed += z % 2 ? -(z + 1) / 2 : z / 2;
    cumulative += varint();
    out[r * 2] = seed; out[r * 2 + 1] = cumulative;
  }
  if (p !== bytes.length || cumulative !== total) throw new Error('Corrupt outcome catalogue');
  return out;
}
